#!/usr/bin/env bash

set -euo pipefail

root_dir="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd -P)"
env_file="${1:?Usage: verify-compose-lifecycle.sh ENV_FILE}"
project_name="${COMPOSE_PROJECT_NAME:-trace-lifecycle}"
compose=(docker compose --project-name "$project_name" --env-file "$env_file" -f "$root_dir/compose.yaml" -f "$root_dir/compose.e2e.yaml" --profile e2e)

set -a
# The environment file is generated by write-compose-env.sh and is trusted
# input for this CI helper. Exporting it also gives the helper the published
# host port selected for this run.
# shellcheck disable=SC1090
source "$env_file"
set +a

backend_url="http://127.0.0.1:${BACKEND_HTTP_PORT:?BACKEND_HTTP_PORT is required}"

wait_for_ready() {
  local attempts="${1:-60}"
  for _ in $(seq 1 "$attempts"); do
    if curl --silent --show-error --fail "$backend_url/health/ready" >/dev/null; then
      return 0
    fi
    sleep 1
  done
  echo "Compose smoke check failed: backend did not become ready" >&2
  return 1
}

cleanup() {
  "${compose[@]}" down --volumes --remove-orphans
}
trap cleanup EXIT

"${compose[@]}" up --build --wait backend email-worker audit-worker
for service in backend email-worker audit-worker; do
  if ! "${compose[@]}" ps --status running --services | grep -Fxq "$service"; then
    echo "Compose smoke check failed: $service is not running" >&2
    "${compose[@]}" ps -a >&2
    exit 1
  fi
done
wait_for_ready

"${compose[@]}" stop redis
for _ in {1..20}; do
  if [[ "$(curl --silent --output /dev/null --write-out '%{http_code}' "$backend_url/health/ready")" == "503" ]]; then
    break
  fi
  sleep 1
done
[[ "$(curl --silent --output /dev/null --write-out '%{http_code}' "$backend_url/health/ready")" == "503" ]]

"${compose[@]}" start redis
wait_for_ready
"${compose[@]}" restart backend
wait_for_ready
